<template>
  <div class="rules-page">
    <div class="page-hero"><div><span class="eyebrow">TRADING PLAYBOOK</span><h2>交易规则</h2><p>把买入、卖出和风险控制写成可重复执行的检查清单。</p></div><el-button type="primary" @click="openRule()">新建规则</el-button></div>
    <div class="rule-layout">
      <aside class="rule-sidebar"><div class="sidebar-title">规则库 <span>{{ filteredRules.length }}</span></div><el-input v-model="keyword" clearable placeholder="搜索规则"/><div class="rule-nav"><button v-for="item in categories" :key="item.value" :class="{active:category===item.value}" @click="category=item.value">{{ item.label }}<small>{{ countByCategory(item.value) }}</small></button></div></aside>
      <main><div v-if="filteredRules.length" class="rule-grid"><el-card v-for="rule in filteredRules" :key="rule.id" class="rule-card"><template #header><div class="rule-head"><div><el-tag size="small" :type="rule.enabled?'success':'info'">{{ rule.enabled?'启用':'停用' }}</el-tag><span class="rule-category">{{ categoryLabel(rule.category) }}</span></div><el-dropdown><el-button text>···</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="openRule(rule)">编辑</el-dropdown-item><el-dropdown-item @click="toggleRule(rule)">{{ rule.enabled?'停用':'启用' }}</el-dropdown-item><el-dropdown-item divided @click="removeRule(rule.id)">删除</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div><h3>{{ rule.name }}</h3></template><p class="rule-summary">{{ rule.summary || '尚未填写规则摘要' }}</p><div class="rule-block"><span>触发条件</span><p>{{ rule.buyConditions || '未定义' }}</p></div><div class="rule-block"><span>禁止条件</span><p>{{ rule.forbiddenConditions || '未定义' }}</p></div><div class="rule-foot"><span>最大仓位 {{ rule.maxPosition == null ? '-' : rule.maxPosition + '%' }}</span><span>版本 {{ rule.version }}</span></div><div class="rule-stats"><span>使用 {{ stat(rule.id).totalTrades }} 次</span><span>按计划 {{ stat(rule.id).plannedTrades }} 次</span><span>持仓中 {{ stat(rule.id).openTrades }} 笔</span></div></el-card></div><el-empty v-else description="还没有规则，先建立你的第一套交易规则"/></main>
    </div>
    <el-dialog v-model="visible" :title="editingId ? '编辑交易规则' : '新建交易规则'" width="min(720px, 96vw)" :close-on-click-modal="false"><el-form label-position="top"><div class="form-grid"><el-form-item label="规则名称"><el-input v-model="form.name" placeholder="例如：趋势突破买入"/></el-form-item><el-form-item label="分类"><el-select v-model="form.category"><el-option v-for="item in categories.filter(x=>x.value)" :key="item.value" :label="item.label" :value="item.value"/></el-select></el-form-item><el-form-item label="最大仓位 %"><el-input-number v-model="form.maxPosition" :min="0" :max="100"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.enabled" active-text="启用" inactive-text="停用"/></el-form-item></div><el-form-item label="一句话摘要"><el-input v-model="form.summary"/></el-form-item><el-form-item label="买入/执行条件"><el-input v-model="form.buyConditions" type="textarea" :rows="4" placeholder="满足哪些事实和信号才允许执行？"/></el-form-item><el-form-item label="禁止条件"><el-input v-model="form.forbiddenConditions" type="textarea" :rows="3" placeholder="出现哪些情况必须放弃？"/></el-form-item><el-form-item label="卖出与风险控制"><el-input v-model="form.sellConditions" type="textarea" :rows="3"/></el-form-item><el-form-item label="执行前检查清单"><el-input v-model="form.checklist" type="textarea" :rows="3" placeholder="一行一个检查项"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="saveRule">保存规则</el-button></template></el-dialog>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import * as api from '@/api/tradingReview';
import type { TradingRule as ApiRule, TradingRulePayload, TradingRuleStats } from '@/api/tradingReview';
type Rule=ApiRule;
const categories=[{label:'全部规则',value:''},{label:'买入规则',value:'BUY'},{label:'卖出规则',value:'SELL'},{label:'风控规则',value:'RISK'},{label:'仓位规则',value:'POSITION'}];
const rules=ref<Rule[]>([]),ruleStats=ref<TradingRuleStats[]>([]),keyword=ref(''),category=ref(''),visible=ref(false),editingId=ref<number>();
const blank=():TradingRulePayload=>({name:'',category:'BUY',summary:'',buyConditions:'',forbiddenConditions:'',sellConditions:'',checklist:'',maxPosition:30,enabled:true});
const form=reactive<TradingRulePayload>(blank());
const filteredRules=computed(()=>rules.value.filter(rule=>(!category.value||rule.category===category.value)&&(!keyword.value||[rule.name,rule.summary,rule.buyConditions,rule.forbiddenConditions].some(value=>(value||'').toLowerCase().includes(keyword.value.toLowerCase())))).sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||'')));
function categoryLabel(value:string){return categories.find(item=>item.value===value)?.label||value;}function countByCategory(value:string){return value?rules.value.filter(item=>item.category===value).length:rules.value.length;}function stat(id:number){return ruleStats.value.find(item=>item.ruleId===id)||{totalTrades:0,plannedTrades:0,openTrades:0,closedTrades:0};}
function openRule(rule?:Rule){editingId.value=rule?.id;Object.assign(form,rule?{...rule}:{...blank()});visible.value=true;}
async function saveRule(){if(!form.name.trim()||!form.buyConditions.trim()){ElMessage.warning('请填写规则名称和执行条件');return;}await api.saveTradingRule(form,editingId.value);visible.value=false;editingId.value=undefined;ElMessage.success('规则已保存');await load();}
async function toggleRule(rule:Rule){await api.toggleTradingRule(rule.id,!rule.enabled);await load();}async function removeRule(ruleId:number){await ElMessageBox.confirm('删除后不可恢复，是否继续？','确认删除',{type:'warning'});await api.removeTradingRule(ruleId);await load();}async function load(){const [ruleResponse,statsResponse]=await Promise.all([api.listTradingRules(),api.listTradingRuleStats()]);rules.value=ruleResponse.data;ruleStats.value=statsResponse.data;}
onMounted(load);
</script>
<style scoped>
.rules-page{display:flex;flex-direction:column;gap:18px}.rule-stats{display:flex;gap:10px;margin-top:12px;color:#64748b;font-size:11px;flex-wrap:wrap}.rule-stats span{padding:4px 8px;border-radius:99px;background:#f1f5f9}.page-hero{display:flex;justify-content:space-between;align-items:flex-end;padding:28px 30px;border-radius:24px;color:#fff;background:linear-gradient(135deg,#172554,#1d4ed8 58%,#0f766e);box-shadow:0 16px 36px rgb(15 23 42 / 14%)}.eyebrow{font-size:11px;letter-spacing:.2em;color:#bfdbfe}.page-hero h2{margin:7px 0;font-size:30px}.page-hero p{margin:0;color:#dbeafe}.rule-layout{display:grid;grid-template-columns:220px 1fr;gap:18px}.rule-sidebar{padding:18px;border:1px solid #e2e8f0;border-radius:18px;background:#fff;height:max-content}.sidebar-title{display:flex;justify-content:space-between;margin-bottom:14px;font-weight:750;color:#0f172a}.sidebar-title span{color:#2563eb}.rule-nav{display:flex;flex-direction:column;gap:5px;margin-top:15px}.rule-nav button{display:flex;justify-content:space-between;padding:10px 11px;border:0;border-radius:10px;background:transparent;color:#64748b;text-align:left;cursor:pointer}.rule-nav button.active,.rule-nav button:hover{background:#eff6ff;color:#2563eb}.rule-nav small{color:#94a3b8}.rule-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.rule-card{border:1px solid #e2e8f0!important;border-radius:16px!important}.rule-card :deep(.el-card__header){padding:16px 18px 12px}.rule-card :deep(.el-card__body){padding:0 18px 18px}.rule-head{display:flex;justify-content:space-between;align-items:center}.rule-category{margin-left:8px;color:#94a3b8;font-size:12px}.rule-card h3{margin:12px 0 0;color:#0f172a}.rule-summary{color:#475569;line-height:1.6}.rule-block{padding:10px 12px;margin-top:10px;border-radius:10px;background:#f8fafc}.rule-block span{color:#94a3b8;font-size:11px}.rule-block p{margin:4px 0 0;color:#475569;font-size:13px;line-height:1.55}.rule-foot{display:flex;justify-content:space-between;margin-top:15px;color:#94a3b8;font-size:12px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.form-grid :deep(.el-select),.form-grid :deep(.el-input-number){width:100%}@media(max-width:800px){.rule-layout{grid-template-columns:1fr}.rule-grid{grid-template-columns:1fr}}@media(max-width:600px){.page-hero{align-items:flex-start;flex-direction:column;gap:16px;padding:22px 18px}.form-grid{grid-template-columns:1fr}}
</style>

<style scoped>
.rule-card .rule-summary,.rule-card .rule-block p{white-space:pre-line;overflow-wrap:anywhere;word-break:break-word}
.rule-card .rule-summary{min-height:28px}
</style>
